CREATE OR REPLACE FUNCTION zoi.auto_seo_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_cat_slug text;
  v_cat_label text;
  v_slug text;
  v_title text;
  v_desc text;
BEGIN
  IF NEW.primary_category_id IS NOT NULL THEN
    SELECT c.slug, c.label_en INTO v_cat_slug, v_cat_label
    FROM zoi.categories c WHERE c.id = NEW.primary_category_id;
  END IF;

  v_slug := coalesce(NEW.slug, zoi.seo_slug(NEW.name || '-' || coalesce(NEW.city,'')));

  IF NEW.schema_type IS NULL OR length(NEW.schema_type)=0 THEN
    NEW.schema_type := zoi.schema_type(NEW.entity_type, coalesce(v_cat_slug,''));
  END IF;

  IF NEW.canonical_path IS NULL OR length(NEW.canonical_path)=0 THEN
    NEW.canonical_path := '/' || NEW.entity_type || '/' || v_slug;
  END IF;

  IF NEW.meta_title IS NULL OR length(NEW.meta_title)=0 THEN
    v_title := NEW.name
      || coalesce(' — ' || zoi.seo_pluralize(v_cat_label), '')
      || coalesce(' in ' || NEW.city, '')
      || ' | Zoi';
    IF length(v_title) > 66 THEN
      v_title := NEW.name || coalesce(' in ' || NEW.city, '') || ' | Zoi';
    END IF;
    IF length(v_title) > 66 THEN
      v_title := left(NEW.name, 60) || ' | Zoi';
    END IF;
    NEW.meta_title := v_title;
  END IF;

  IF NEW.meta_description IS NULL OR length(NEW.meta_description)=0 THEN
    IF NEW.description IS NOT NULL AND length(NEW.description) >= 30
       AND NEW.description !~* '^https?://' THEN
      v_desc := left(NEW.description, 158);
    ELSE
      v_desc := NEW.name
        || coalesce(' in ' || NEW.city, '')
        || coalesce(', ' || NEW.country, '')
        || '. Listed on Zoi, the Greek community directory.';
    END IF;
    NEW.meta_description := v_desc;
  END IF;

  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION zoi.ensure_listing_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare base text; cand text; n int := 0;
begin
  if new.slug is not null and length(new.slug) > 0 then
    return new;
  end if;
  begin
    if new.canonical_path is not null and length(new.canonical_path) > 0 then
      base := substring(new.canonical_path from '^/[^/]+/(.+)$');
    end if;
    if base is null or length(base) = 0 then
      base := zoi.seo_slug(coalesce(new.name,'') || '-' || coalesce(new.city,''));
    end if;
    if base is null or length(base) = 0 then
      return new;                              -- cannot derive; keep today's behavior
    end if;
    cand := base;
    while exists (select 1 from zoi.listings x where x.slug = cand and x.id <> new.id) loop
      n := n + 1;
      cand := base || '-' || n;
      if n > 50 then
        cand := base || '-' || substr(replace(new.id::text,'-',''),1,8);
        exit;
      end if;
    end loop;
    new.slug := cand;
  exception when others then
    null;                                      -- never break the write
  end;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION zoi.geography_source_listing_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l zoi.listings;generation bigint;previous zoi.geography_repair_jobs;became_unowned_public boolean:=false;current_hash text;authority_hash text;BEGIN
 -- Deferred events must use the final row, not an intermediate NEW snapshot.
 SELECT * INTO l FROM zoi.listings WHERE id=NEW.id;
 IF l.id IS NULL OR NOT zoi.geography_source_eligible(l) OR public.geography_reviewed_point(l.id) IS NOT NULL THEN RETURN NULL;END IF;
 IF TG_OP='UPDATE' THEN became_unowned_public:=OLD.owner_user_id IS NOT NULL OR OLD.owner_workspace_id IS NOT NULL OR OLD.publish_status IS DISTINCT FROM 'published' OR (OLD.moderation_status IS DISTINCT FROM 'clean' AND OLD.moderation_status IS DISTINCT FROM 'cleared') OR OLD.marketplace_status='hidden';END IF;
 current_hash:=zoi.geography_repair_input(l);authority_hash:=zoi.geography_source_authority_input(l);generation:=zoi.geography_source_generation(l.id);
 SELECT * INTO previous FROM zoi.geography_repair_jobs WHERE listing_id=l.id AND strategy='official_sources_v1'AND source_generation=generation ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT coalesce(became_unowned_public,false) AND previous.id IS NOT NULL AND previous.input_fingerprint=current_hash AND(previous.source_authority_fingerprint=authority_hash OR(previous.source_authority_fingerprint=''AND(TG_OP='INSERT'OR zoi.geography_source_authority_input(OLD)=authority_hash)))THEN
  -- Same final input/generation: terminal history does not cause endless retries.
  -- Still add a missing supporting lane idempotently when appropriate.
  PERFORM zoi.geography_source_enqueue_one(l,'publisher_profiles_v1',generation);RETURN NULL;
 END IF;
 generation:=generation+1;
 PERFORM zoi.geography_source_enqueue_one(l,'official_sources_v1',generation);
 PERFORM zoi.geography_source_enqueue_one(l,'publisher_profiles_v1',generation);
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION zoi.guard_listing_quality_receipts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE prior_receipt jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN prior_receipt:=OLD.profile->'_coverage';END IF;
 IF (current_user IN('anon','authenticated') OR current_setting('request.jwt.claim.role',true) IN('anon','authenticated') OR coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb->>'role' IN('anon','authenticated')) AND NEW.profile->'_coverage' IS DISTINCT FROM prior_receipt THEN RAISE EXCEPTION 'quality_receipts_service_only';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zoi.maintenance_candidate_ids()
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s jsonb;after_id uuid;chosen uuid[];
BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtextextended('zoi.run_maintenance',0)) THEN RETURN ARRAY[]::uuid[];END IF;
 SELECT value INTO s FROM zoi.delivery_state WHERE key='listing_score_cursor_v1' FOR UPDATE;
 IF s IS NULL OR jsonb_typeof(s) IS DISTINCT FROM 'object' OR s->'version' IS DISTINCT FROM '1'::jsonb OR NOT(s?'after_id') OR EXISTS(SELECT 1 FROM jsonb_object_keys(s)k WHERE k NOT IN('version','after_id')) THEN RAISE EXCEPTION 'maintenance_candidates_cursor_invalid';END IF;
 IF s->'after_id' IS DISTINCT FROM 'null'::jsonb THEN
  IF jsonb_typeof(s->'after_id') IS DISTINCT FROM 'string' OR coalesce(s->>'after_id','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'maintenance_candidates_cursor_invalid';END IF;
  after_id:=(s->>'after_id')::uuid;
 END IF;
 -- Two bounded PK seeks; the second runs only when the first found zero IDs.
 -- It is never a second batch: at most 1000 IDs are selected in total.
 IF after_id IS NULL THEN
  SELECT coalesce(array_agg(c.id ORDER BY c.id),ARRAY[]::uuid[]) INTO chosen FROM(SELECT l.id FROM zoi.listings l ORDER BY l.id LIMIT 1000)c;
 ELSE
  SELECT coalesce(array_agg(c.id ORDER BY c.id),ARRAY[]::uuid[]) INTO chosen FROM(SELECT l.id FROM zoi.listings l WHERE l.id>after_id ORDER BY l.id LIMIT 1000)c;
  IF cardinality(chosen)=0 THEN
   SELECT coalesce(array_agg(c.id ORDER BY c.id),ARRAY[]::uuid[]) INTO chosen FROM(SELECT l.id FROM zoi.listings l ORDER BY l.id LIMIT 1000)c;
  END IF;
 END IF;
 IF cardinality(chosen)>0 THEN
  UPDATE zoi.delivery_state SET value=jsonb_build_object('version',1,'after_id',chosen[cardinality(chosen)]::text),updated_at=clock_timestamp() WHERE key='listing_score_cursor_v1';
 END IF;
 RETURN chosen;
END $function$

CREATE OR REPLACE FUNCTION zoi.maintenance_event_date(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
BEGIN
  IF p_value IS NULL OR p_value !~ '^\d{4}-\d{2}-\d{2}($|T| )' THEN RETURN NULL; END IF;
  RETURN left(p_value,10)::date;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION zoi.skip_noop_listing_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'zoi', 'public'
AS $function$
BEGIN
  IF (to_jsonb(NEW) - 'updated_at') = (to_jsonb(OLD) - 'updated_at') THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION zoi.tg_apply_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_gate jsonb;
begin
 if new.publish_status is null or new.publish_status in ('draft','published') then
  v_gate:=zoi.publish_gate(new.name,new.entity_type,new.primary_category_id,new.city,new.country,new.phone,new.address,new.website);
  if new.publish_status is distinct from 'draft' then
   if (v_gate->>'ok')::boolean then new.publish_status:='published';
   else new.publish_status:='pending_review';end if;
  end if;
  new.profile:=coalesce(new.profile,'{}'::jsonb)||jsonb_build_object('gate',jsonb_build_object(
   'ok',v_gate->'ok','fails',v_gate->'fails','warnings',v_gate->'warnings',
   'checked_at',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')));
  new.completeness_score:=round(((v_gate->>'quality_score')::numeric/100.0),3);
 end if;
 return new;
end;
$function$

